package com.projecteden.dataset;
import java.nio.file.*; import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.dataformat.yaml.YAMLFactory; import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule; import org.springframework.stereotype.Component; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.beans.factory.annotation.Value;
@Component @ConditionalOnProperty(prefix="eden.benchmark.orchestration",name="enabled",havingValue="true")
public class FilesystemQualityGateStore {
 private final DatasetPathResolver paths; private final ObjectMapper yaml=new ObjectMapper(new YAMLFactory()).registerModule(new JavaTimeModule());
 public FilesystemQualityGateStore(@Value("${eden.dataset.root:}") String root){paths=new DatasetPathResolver(root==null||root.isBlank()?Path.of(System.getenv().getOrDefault("EDEN_DATASET_ROOT",System.getProperty("user.home")+"/.project-eden/datasets")):Path.of(root));}
 public void persist(VisionDatasetId d,BenchmarkQualityGateResult gate){Path dir=paths.benchmarkDirectory(d,gate.benchmarkRunId());Path target=dir.resolve("quality-gate.yml");if(Files.exists(target))throw new IllegalArgumentException("QUALITY_GATE_IMMUTABLE");try{Files.createDirectories(dir);BenchmarkRun run=yaml.readValue(dir.resolve("benchmark.yml").toFile(),BenchmarkRun.class);atomic(target,yaml.writerWithDefaultPrettyPrinter().writeValueAsBytes(gate));String report="# Benchmark "+run.runId()+"\n\n"+(run.status()==BenchmarkStatus.FAILED?"## Failure\n- Code: "+run.failure().code()+"\n- Message: "+run.failure().safeMessage()+"\n- Processed Cases: "+run.failure().processedCases()+"\n- Total Cases: "+run.failure().totalCases()+"\n- Failed At: "+run.failure().failedAt()+"\n\n":"")+"## Quality Gate\n- Decision: "+gate.decision()+"\n- Policy Version: "+gate.policyVersion()+"\n- Case Count: "+gate.caseCount()+"\n- Sample Sufficiency: "+(gate.decision()!=BenchmarkQualityDecision.INSUFFICIENT_SAMPLE)+"\n- Reasons: "+gate.reasons()+"\n\n### Evidence\nNo additional evidence is persisted by policy v1.\n";atomic(dir.resolve("report.md"),report.getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(java.io.IOException e){throw new IllegalStateException("QUALITY_GATE_WRITE_FAILED",e);}}
 private void atomic(Path target,byte[] bytes)throws java.io.IOException{Path tmp=target.resolveSibling(target.getFileName()+".tmp");Files.write(tmp,bytes);try{Files.move(tmp,target,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(tmp,target,StandardCopyOption.REPLACE_EXISTING);}}
}
